		&= \sum_{a : \tr(a (r +r')) = c } \hat{M}^{(\Point,W),u}_a \notag\\
		&= \hat{M}^{(\Point,W),u,r+r'}_c\;,\label{eq:m-lin}
	\end{align}
	where the second line follows from projectivity of $\{\hat{M}^{(\Point,W),u}_a\}$.

